# The pattern [3,4,5,6,7,8,9,1,2,2,3,3,...] 

def build_output_period3():
    result = []
    for r in range(23):
        if r == 0:
            # Pattern starts with 2
            result.append([2,3,4,5,6,7,8,9,1,2,3,4,5,6,7,8,9,1,2,3,4,5,6])
        elif r == 1:
            # Has [3,3] - dedup row
            result.append([3,3,4,5,6,7,8,9,1,2,3,4,5,6,7,8,9,1,2,3,4,5,6])
        elif r == 2:
            # Has [4,4] - dedup row
            result.append([3,4,4,5,6,7,8,9,1,2,3,4,5,6,7,8,9,1,2,3,4,5,6])
        elif r == 3:
            # Has [5,5] - dedup row
            result.append([3,4,5,5,6,7,8,9,1,2,3,4,5,6,7,8,9,1,2,3,4,5,6])
        else:
            # Standard pattern
            result.append([3,4,5,6,7,8,9,1,2,2,3,4,5,6,7,8,9,1,2,3,4,5,6])
    return result

# Actually rows 0-3 in INPUT have no dups in some cols
# But OUTPUT should have dups! That's the transformation

output = build_output_period3()
action = {"action": "submit", "grid": output}
print(json.dumps(action))

